// Card drops: the same roll the addon makes in game (HatedTCGDrops.lua), made again here from the kill's spawn id
// (or a boss's own key) with the tables in drop_data.ts / HatedTCGDropData.lua (generated by tools/tcg_drops.py).
import { DROPS as X } from './drop_data.ts';

function rng(seed: string) {
  let s = 7;
  for (const b of new TextEncoder().encode(seed)) s = (s * 31 + b) % 2147483646 + 1;
  return (n: number) => { s = (s * 48271) % 2147483647; return s % n; };
}

// is this a group the tables know? ("n.<creature>", "t.<TRIBE>" or ""; addon 3.8.0 also sent "c.<CLASS>", which now drops nothing)
export const validGroup = (g: string) => g === '' || (g.startsWith('n.') && !!X.named[g.slice(2)])
  || (g.startsWith('t.') && !!X.tribes[g.slice(2)]) || (g.startsWith('c.') && !!X.heroes[g.slice(2)]);
export const validClass = (c: string) => c === '' || !!X.heroes[c];

// kind: normal / elite / rare / worldboss / dungeonboss / raidboss -> { drop, hero } card dbf ids (or undefined), and
// whether each is holographic (Rare and up, 1 in holoOdds)
export function roll(key: string, group: string, cls: string, kind: string): { drop?: number; hero?: number; dropHolo: boolean; heroHolo: boolean } {
  const r = rng(`hated-drop-${X.version}|${key}`);
  const { drop, hero } = pick(r, group, cls, kind);
  const dropHolo = drop !== undefined && (X.rarity[drop] || 1) >= 3 && r(X.holoOdds) === 0;
  const heroHolo = hero !== undefined && r(X.holoOdds) === 0;
  return { drop, hero, dropHolo, heroHolo };
}
function pick(r: (n: number) => number, group: string, cls: string, kind: string): { drop?: number; hero?: number } {
  const out: { drop?: number; hero?: number } = {};
  if (cls !== '' && X.heroes[cls] && r(X.heroOdds) === 0) { const h = X.heroes[cls]; out.hero = h[r(h.length)]; }
  const named: number[] | undefined = group.startsWith('n.') ? X.named[group.slice(2)] : undefined;
  const pools: number[][] | undefined = group.startsWith('t.') ? X.tribes[group.slice(2)] : undefined;
  if (!named && !pools) return out;                                // not a creature any card belongs to
  let odds = X.odds[kind] || X.odds.normal;
  if (named) odds = Math.min(odds, X.odds.named);
  if (r(odds) !== 0) return out;
  if (named) { out.drop = named[r(named.length)]; return out; }
  const pct: number[] = (kind === 'normal' || kind === 'elite') ? X.rarityPct.low : X.rarityPct.high;
  let x = r(100), want = 5;
  for (let i = 1; i <= 5; i++) { x -= pct[i - 1]; if (x < 0) { want = i; break; } }
  for (let step = 0; step <= 4; step++) {
    for (const i of step === 0 ? [want] : [want - step, want + step]) {
      const p = pools[i - 1];
      if (p && p.length) { out.drop = p[r(p.length)]; return out; }
    }
  }
  return out;
}
export const killKind = (cls: string) => cls === 'worldboss' ? 'worldboss' : (cls === 'rare' || cls === 'rareelite') ? 'rare' : cls === 'elite' ? 'elite' : 'normal';
export const RARITY = ['common', 'uncommon', 'rare', 'epic', 'legendary'];
export const rarityOf = (dbf: number) => RARITY[(X.rarity[dbf] || 1) - 1];
